using System;
using System.Collections;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
class WorkEndUiTests {
 static int checks,failures;static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}
 static void Check(string n,bool v){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}
 static Button Find(DependencyObject root,string text){var b=root as Button;if(b!=null&&Convert.ToString(b.Content)==text)return b;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=Find(VisualTreeHelper.GetChild(root,i),text);if(found!=null)return found;}return null;}
 static object Field(object o,string n){return o.GetType().GetField(n).GetValue(o);}static void Click(DependencyObject root,string text){var b=Find(root,text);if(b==null)throw new Exception("Missing: "+text);b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
 [STAThread]static int Main(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();var runtime=(SkillRuntime)Get(pet,"skills");runtime.Engine.SetWorkEnd(true,1087,1);Call(pet,"OpenTerminal");var terminal=(TerminalWindow)Get(pet,"terminal");terminal.ShowPage("下班倒计时");terminal.UpdateLayout();var page=Get(pet,"skillsWindow");var editors=(IList)Get(page,"endEditors");Check("legacy time is retained in selectors",editors.Count==1&&((ComboBox)Field(editors[0],"Hour")).SelectedIndex==18&&((ComboBox)Field(editors[0],"Minute")).SelectedIndex==7);
 Click(terminal,"＋中午");terminal.UpdateLayout();Check("add noon creates independent row",editors.Count==2);var noon=editors[1];Check("new row stays disabled until selected",((CheckBox)Field(noon,"Enabled")).IsChecked==false);Check("picker covers every hour and minute",((ComboBox)Field(noon,"Hour")).Items.Count==24&&((ComboBox)Field(noon,"Minute")).Items.Count==60);((CheckBox)Field(noon,"Enabled")).IsChecked=true;((ComboBox)Field(noon,"Hour")).SelectedIndex=12;((ComboBox)Field(noon,"Minute")).SelectedIndex=30;Click(terminal,"保存下班设置");Check("save applies selected time",runtime.Engine.WorkEndSlots().Length==2&&runtime.Engine.WorkEndSlots()[1].MinuteOfDay==750);var restored=new SkillRuntime(AppDomain.CurrentDomain.BaseDirectory);Check("saved multiple shifts load from disk",restored.Engine.WorkEndSlots().Length==2&&restored.Engine.WorkEndSlots()[1].MinuteOfDay==750);
 Click(terminal,"＋晚上");terminal.UpdateLayout();Check("evening preset available",editors.Count==3);var rows=(StackPanel)Get(page,"endSlots");Click(rows.Children[2],"删除");Click(terminal,"保存下班设置");Check("delete removes only selected shift",editors.Count==2&&runtime.Engine.WorkEndSlots().Length==2);
 terminal.UpdateLayout();var panel=(FrameworkElement)terminal.Content;var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)panel.ActualWidth,(int)panel.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(panel);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var file=System.IO.File.Create(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"work-end-ui.png")))encoder.Save(file);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}Console.WriteLine("Checks: "+checks+" Failures: "+failures);return failures==0?0:1;}
}
